def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Parse recent and aggregate info without importing anything.
    # Track opponent defection streak and cooperation rate.
    opp_coops = 0
    my_coops = 0
    opp_defects = 0
    for me, opp in history:
        if opp == 'C':
            opp_coops += 1
        else:
            opp_defects += 1
        if me == 'C':
            my_coops += 1

    last_me, last_opp = history[-1]

    # Opponent defection streak (consecutive D at end)
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    # My defection streak at end
    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    opp_rate = opp_coops / n

    # Opening: cooperate to invite mutual cooperation.
    if n < 3:
        return 'C'

    # Very cooperative opponent: keep cooperating, but probe occasionally
    # to detect exploitation and to grab payoff, avoiding endgame traps.
    if opp_rate >= 0.85:
        # If opponent suddenly defects, retaliate quickly but be willing to recover.
        if last_opp == 'D':
            return 'D'
        # Rare deterministic probes, avoiding final rounds where retaliation hurts.
        if n < 92 and my_d_streak == 0 and n % 19 == 0:
            return 'D'
        return 'C'

    # Very defection-heavy opponent: defect, with rare probes for re-establishing.
    if opp_rate <= 0.2:
        if n > 10 and opp_d_streak >= 6 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Strong sustained defector (recent window heavily D): stay in D.
    if n >= 8:
        window = history[-8:]
        w_d = 0
        for _, o in window:
            if o == 'D':
                w_d += 1
        if w_d >= 7:
            return 'D'
        # Mostly-cooperative recent window: cooperate unless we were just defected on.
        if w_d <= 1:
            if last_opp == 'D':
                return 'D'
            return 'C'

    # Detect periodic alternators / short-cycle exploiters: if opponent's last
    # few moves fit a simple alternating pattern, defect now.
    if n >= 5:
        alt = True
        for i in range(n - 4, n):
            a = history[i - 1][1]
            b = history[i][1]
            if a == b:
                alt = False
                break
        if alt and n >= 6:
            # Alternating opponent - defect when they're about to cooperate,
            # cooperate when they're about to defect, approximated by copying
            # their expected next move's opposite.
            return 'D' if last_opp == 'C' else 'D'

    # Tit-for-tat with measured forgiveness: retaliate to defection, but
    # forgive quickly when opponent's overall behavior is cooperative
    # (matches four_D_ALLC and one_D_TFT recoveries).
    if last_opp == 'D':
        # If opponent has been fairly cooperative overall and just defected
        # once (not a sustained streak), forgive to restore mutual CC.
        if opp_d_streak == 1 and opp_rate > 0.5:
            # Forgive with high probability; deterministic recovery for
            # a single unexpected D.
            if n < 95 and rng.random() < 0.15:
                return 'D'
            return 'C'
        # Multi-round defection streak: punish, but try to break DD loops.
        if opp_d_streak >= 3:
            # If we've also been defecting a while, occasionally offer C to
            # break the cycle - helps against four_D_TFT and similar.
            if my_d_streak >= 3 and n < 90 and rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    if last_me == 'D':
        # We defected and they cooperated: don't keep exploiting a forgiving
        # opponent too hard, return to cooperation to keep payoff stream stable.
        return 'C'

    # Both cooperated last round.
    # Guard against endgame exploitation of very forgiving opponents.
    if n >= 92 and opp_rate > 0.6:
        return 'C'
    return 'C'
